/* @lc app=leetcode id=1713 lang=kotlin */ class Solution { fun minOperations(target: IntArray, arr: IntArray): Int = target.withIndex().associate { (i, v) -> v to i }.let { pos -> arr.asList().mapNotNull { pos[it] }.fold(ArrayList<Int>()) { t, x -> t.also { l -> java.util.Collections.binarySearch(l, x).let { r -> if (r < 0) (-r - 1).let { ins -> if (ins == l.size) l.add(x) else l.set(ins, x) } } } }.size.let { target.size - it } } }